import{_ as d,C as p,o as t,c,a0 as i,b as o,w as a,a as n,E as l,a1 as r}from"./chunks/framework.CzVS_xMp.js";const h="/ai-data-center-systems/assets/gpu-numa-locality.BfPfnC0S.svg",P=JSON.parse('{"title":"Keeping GPU Workloads NUMA-Local in Kubernetes","description":"","frontmatter":{},"headers":[],"relativePath":"systems-performance/articles/keeping-gpu-workloads-numa-local-in-kubernetes.ko.md","filePath":"systems-performance/articles/keeping-gpu-workloads-numa-local-in-kubernetes.ko.md","lastUpdated":1788432796000}'),k={name:"systems-performance/articles/keeping-gpu-workloads-numa-local-in-kubernetes.ko.md"};function u(g,e,y,m,C,b){const s=p("Mermaid");return t(),c("div",null,[e[2]||(e[2]=i(`<h1 id="keeping-gpu-workloads-numa-local-in-kubernetes" tabindex="-1">Keeping GPU Workloads NUMA-Local in Kubernetes <a class="header-anchor" href="#keeping-gpu-workloads-numa-local-in-kubernetes" aria-label="Permalink to &quot;Keeping GPU Workloads NUMA-Local in Kubernetes&quot;">​</a></h1><blockquote><p>Ronak Nathani, &quot;Keeping GPU Workloads NUMA-Local in Kubernetes&quot; 요약 노트. 원문: <a href="https://ronaknathani.com/blog/2026/05/keeping-gpu-workloads-numa-local-in-kubernetes/" target="_blank" rel="noreferrer">https://ronaknathani.com/blog/2026/05/keeping-gpu-workloads-numa-local-in-kubernetes/</a></p></blockquote><h2 id="한-줄-요지" tabindex="-1">한 줄 요지 <a class="header-anchor" href="#한-줄-요지" aria-label="Permalink to &quot;한 줄 요지&quot;">​</a></h2><p>GPU workload에서 CPU가 request preparation, batching, dataloader, pinned memory staging처럼 GPU로 가는 data path에 있다면, Kubernetes의 기본 resource scheduling만으로는 부족하다. CPU, GPU, memory가 같은 NUMA domain에 들어오도록 kubelet policy, topology-aware scheduling, workload sizing을 함께 설계해야 한다.</p><h2 id="이-글의-위치" tabindex="-1">이 글의 위치 <a class="header-anchor" href="#이-글의-위치" aria-label="Permalink to &quot;이 글의 위치&quot;">​</a></h2><p>이 글은 NUMA architecture의 이론 설명보다는 Kubernetes에서 NUMA locality를 실제로 지키는 운영 방법에 초점을 둔다. 핵심 질문은 다음이다.</p><ul><li>GPU와 CPU가 같은 NUMA node에 있는가?</li><li>CPU request가 exclusive CPU allocation을 받을 수 있는 형태인가?</li><li>GPU device plugin이 NUMA topology hint를 제공하는가?</li><li>Pod가 한 NUMA node에 들어가지 않을 때 조용히 느려지는가, admission 단계에서 실패하는가?</li><li>Scheduler가 node aggregate resource가 아니라 NUMA node별 남은 resource를 보고 배치하는가?</li></ul><p>이 질문은 inference와 training 모두에 걸린다. Inference에서는 p99 tail latency로, training에서는 dataloader wait time, H2D copy time, step time variance로 나타난다.</p><h2 id="numa와-gpu-data-path" tabindex="-1">NUMA와 GPU data path <a class="header-anchor" href="#numa와-gpu-data-path" aria-label="Permalink to &quot;NUMA와 GPU data path&quot;">​</a></h2><p>NUMA는 CPU core가 어느 memory에 접근하느냐에 따라 access latency와 bandwidth가 달라지는 구조다. 2-socket server에서는 socket마다 local memory가 있고, 다른 socket의 memory에 접근하려면 socket interconnect를 건너야 한다. AMD EPYC에서는 BIOS의 NPS(Nodes Per Socket) 설정에 따라 한 socket이 여러 NUMA node로 더 쪼개질 수 있다.</p><p>GPU workload에서 중요한 점은 PCIe device도 특정 CPU socket 또는 root complex에 물리적으로 연결된다는 것이다. GPU가 DMA로 host memory를 읽을 때 그 memory가 GPU와 가까운 NUMA node에 있으면 local path에 가깝지만, 다른 socket의 memory에 있으면 interconnect를 건너게 된다.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Good path:</span></span>
<span class="line"><span>CPU cores + host memory on NUMA 0</span></span>
<span class="line"><span>GPU attached to NUMA 0</span></span>
<span class="line"><span>H2D / DMA stays local</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Bad path:</span></span>
<span class="line"><span>CPU cores or host memory on NUMA 1</span></span>
<span class="line"><span>GPU attached to NUMA 0</span></span>
<span class="line"><span>H2D / DMA crosses socket interconnect</span></span></code></pre></div><p><img src="`+h+'" alt="NUMA-local and cross-socket GPU data paths"></p><p>원문은 한 inference workload에서 CPU가 두 socket에 걸친 pod가 같은 socket 안에 머문 pod보다 load 상태의 p99 tail latency가 30% 이상 높았다고 설명한다. Kubernetes는 이 상황을 자동으로 드러내지 않는다. Pod는 Running이고 health check도 통과하지만, 같은 traffic을 더 느리게 처리한다.</p><p>Training도 같은 원리를 가진다. Data loader worker가 CPU에서 batch를 만들고 GPU로 넘기는 동안 remote memory access와 inter-socket bandwidth contention이 생기면 GPU feeding cadence가 흔들린다. PyTorch performance tuning guide도 training process를 단일 NUMA node에 bind하는 것을 권장한다.</p><h2 id="kubernetes-cpu-isolation-level" tabindex="-1">Kubernetes CPU isolation level <a class="header-anchor" href="#kubernetes-cpu-isolation-level" aria-label="Permalink to &quot;Kubernetes CPU isolation level&quot;">​</a></h2><p>원문은 Kubernetes에서 CPU isolation과 NUMA alignment가 단계적으로 강해진다고 설명한다. 각 단계는 더 강한 성능 isolation을 제공하지만 workload sizing 제약과 failure mode도 늘어난다.</p><table tabindex="0"><thead><tr><th>Level</th><th>Setting</th><th>What it gives</th><th>Main requirement</th></tr></thead><tbody><tr><td>1</td><td><code>cpuManagerPolicy: static</code></td><td>exclusive logical CPU pinning</td><td>Guaranteed QoS, integer CPU request</td></tr><tr><td>2</td><td><code>cpuManagerPolicyOptions: full-pcpus-only=true</code></td><td>physical core 단위 allocation</td><td>SMT thread 수의 배수 CPU request</td></tr><tr><td>3</td><td><code>topologyManagerPolicy: single-numa-node</code></td><td>CPU/device/hugepage topology hint를 단일 NUMA node에 맞춤</td><td>critical resource가 한 NUMA node에 들어야 함</td></tr><tr><td>3+</td><td><code>memoryManagerPolicy: Static</code></td><td>memory request도 topology admission에 포함</td><td><code>reservedMemory</code>, NUMA별 memory capacity planning</td></tr></tbody></table>',18)),(t(),o(r,null,{default:a(()=>[l(s,{id:"mermaid-151",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20A%5BDefault%20Kubernetes%3Cbr%2F%3Eshared%20CPU%20pool%5D%20--%3E%20B%5BLevel%201%3Cbr%2F%3Estatic%20CPU%20Manager%5D%0A%20%20%20%20B%20--%3E%20C%5BLevel%202%3Cbr%2F%3Efull%20physical%20cores%5D%0A%20%20%20%20C%20--%3E%20D%5BLevel%203%3Cbr%2F%3Esingle%20NUMA%20node%5D%0A%20%20%20%20D%20--%3E%20E%5BLevel%203%2B%3Cbr%2F%3Ememory%20included%5D%0A%0A%20%20%20%20A%20--%3E%20A1%5BThreads%20may%20migrate%3Cbr%2F%3Ecache%20locality%20can%20drift%5D%0A%20%20%20%20B%20--%3E%20B1%5BExclusive%20logical%20CPUs%3Cbr%2F%3EGuaranteed%20QoS%20required%5D%0A%20%20%20%20C%20--%3E%20C1%5BNo%20split%20SMT%20sibling%3Cbr%2F%3Eeven%20CPU%20request%20needed%5D%0A%20%20%20%20D%20--%3E%20D1%5BCPU%20%2B%20GPU%20hints%20align%3Cbr%2F%3Eor%20pod%20is%20rejected%5D%0A%20%20%20%20E%20--%3E%20E1%5BCPU%20%2B%20GPU%20%2B%20memory%20fit%3Cbr%2F%3EreservedMemory%20required%5D%0A%0A%20%20%20%20classDef%20primary%20fill%3A%23F5F1EA%2Cstroke%3A%23111111%2Cstroke-width%3A1.4px%2Ccolor%3A%23050505%0A%20%20%20%20classDef%20secondary%20fill%3A%23F3EFE7%2Cstroke%3A%23D8D1C7%2Cstroke-width%3A1.2px%2Ccolor%3A%23050505%0A%20%20%20%20classDef%20note%20fill%3A%23F5F1EA%2Cstroke%3A%23D8D1C7%2Cstroke-width%3A1px%2Ccolor%3A%236F6A63%0A%20%20%20%20classDef%20accent%20fill%3A%23F5F1EA%2Cstroke%3A%23D9392E%2Cstroke-width%3A2px%2Ccolor%3A%23050505%0A%20%20%20%20class%20A%20primary%0A%20%20%20%20class%20B%2CC%20secondary%0A%20%20%20%20class%20D%2CE%20accent%0A%20%20%20%20class%20A1%2CB1%2CC1%2CD1%2CE1%20note%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[n(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=i(`<h2 id="level-1-cpumanagerpolicy-static" tabindex="-1">Level 1: <code>cpuManagerPolicy: static</code> <a class="header-anchor" href="#level-1-cpumanagerpolicy-static" aria-label="Permalink to &quot;Level 1: \`cpuManagerPolicy: static\`&quot;">​</a></h2><p>Kubernetes 기본값에서는 OS scheduler가 container process를 사용 가능한 CPU 위에서 자유롭게 이동시킨다. 전체 CPU utilization 관점에서는 효율적일 수 있지만, cache affinity와 latency consistency에는 불리하다.</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">cpuManagerPolicy</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">static</span></span></code></pre></div><p><code>static</code> policy를 켜면 Guaranteed QoS pod의 integer CPU request를 가진 container가 exclusive logical CPU를 받을 수 있다. Kubelet은 container의 cpuset cgroup을 제한해 해당 process가 배정된 CPU list 안에서만 실행되도록 만든다.</p><p>필요 조건은 다음이다.</p><table tabindex="0"><thead><tr><th>Requirement</th><th>Notes</th></tr></thead><tbody><tr><td><code>requests == limits</code></td><td>모든 container가 Guaranteed QoS 조건을 만족해야 함</td></tr><tr><td>integer CPU request</td><td><code>5.5</code> 같은 fractional CPU는 exclusive CPU 대상이 아님</td></tr><tr><td>init container와 sidecar 확인</td><td>pod QoS는 main container만으로 결정되지 않음</td></tr><tr><td>OS reserved CPU 별도 고려</td><td>host daemon과 kernel thread가 pinned CPU를 방해하지 않게 해야 함</td></tr></tbody></table><p>이 단계만으로도 thread migration이 줄고 container 간 CPU contention이 줄어 성능 일관성이 좋아질 수 있다. 하지만 logical CPU pinning만으로는 physical core 단위 isolation이 보장되지 않는다.</p><h2 id="level-2-full-pcpus-only" tabindex="-1">Level 2: <code>full-pcpus-only</code> <a class="header-anchor" href="#level-2-full-pcpus-only" aria-label="Permalink to &quot;Level 2: \`full-pcpus-only\`&quot;">​</a></h2><p>SMT가 켜진 system에서는 하나의 physical core가 보통 두 logical core로 보인다. 두 container가 같은 physical core의 sibling hyperthread를 하나씩 받으면 L1/L2 cache와 execution resource를 공유한다.</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">cpuManagerPolicyOptions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  full-pcpus-only</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;true&quot;</span></span></code></pre></div><p><code>full-pcpus-only=true</code>는 logical core 조각이 아니라 physical core 전체를 container에 준다. 즉 한 physical core의 SMT sibling이 같은 container로 간다.</p><p>대가도 있다. Exclusive CPU를 받는 container는 SMT thread 수의 배수만큼 CPU를 request해야 한다. 일반적인 2-way SMT에서는 2, 4, 6처럼 even CPU request가 필요하다. 홀수 CPU request를 가진 pinned container는 <code>SMTAlignmentError</code>로 실패할 수 있다.</p><p>운영적으로는 이 옵션을 켜기 전에 기존 workload의 CPU request를 audit해야 한다.</p><h2 id="level-3-single-numa-node" tabindex="-1">Level 3: <code>single-numa-node</code> <a class="header-anchor" href="#level-3-single-numa-node" aria-label="Permalink to &quot;Level 3: \`single-numa-node\`&quot;">​</a></h2><p><code>cpuManagerPolicy: static</code>과 <code>full-pcpus-only</code>는 CPU pinning과 physical core isolation을 제공하지만, 모든 CPU가 같은 NUMA node에서 왔는지는 보장하지 않는다. Kubelet CPU Manager의 기본 packed allocation은 가능한 한 NUMA-local하게 배치하려고 하지만, node fragmentation이 생기면 한 container의 CPU가 여러 NUMA node에 걸칠 수 있다.</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">topologyManagerPolicy</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">single-numa-node</span></span></code></pre></div><p>Topology Manager는 CPU Manager, Device Manager, Memory Manager 같은 component에서 topology hint를 모아 resource allocation이 같은 NUMA node 안에서 가능한지 확인한다. <code>single-numa-node</code>에서는 한 NUMA node가 필요한 hinted resource를 만족하지 못하면 pod admission을 거부한다.</p><p>중요한 caveat가 있다.</p><table tabindex="0"><thead><tr><th>Caveat</th><th>Meaning</th></tr></thead><tbody><tr><td>GPU plugin topology hint 필요</td><td>NVIDIA device plugin 같은 device plugin이 NUMA <code>TopologyInfo</code>를 제공해야 CPU-GPU locality를 강제할 수 있음</td></tr><tr><td>scope 선택 필요</td><td><code>container</code> scope는 container별 alignment, <code>pod</code> scope는 pod effective request 전체 alignment</td></tr><tr><td>sidecar 주의</td><td>logging/metrics sidecar까지 pod scope에 묶으면 불필요하게 admission이 어려워질 수 있음</td></tr><tr><td>memory는 별도</td><td>memory까지 보장하려면 <code>memoryManagerPolicy: Static</code>이 필요</td></tr></tbody></table><h2 id="memory-manager까지-켜는-이유" tabindex="-1">Memory Manager까지 켜는 이유 <a class="header-anchor" href="#memory-manager까지-켜는-이유" aria-label="Permalink to &quot;Memory Manager까지 켜는 이유&quot;">​</a></h2><p>CPU와 GPU가 같은 NUMA node에 있어도 host memory allocation이 remote NUMA node에 잡히면 DMA path가 멀어질 수 있다. 따라서 강한 NUMA alignment에는 memory request도 topology admission에 포함해야 한다.</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">memoryManagerPolicy</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Static</span></span></code></pre></div><p>이 설정을 쓰려면 kubelet의 <code>reservedMemory</code>도 구성해야 한다. 또한 workload의 memory request가 target NUMA node 안에 들어야 한다. 그렇지 않으면 CPU와 GPU는 맞아도 memory 때문에 admission이 실패하거나, 실제 runtime에서 locality가 깨질 수 있다.</p><h2 id="최소-kubelet-configuration" tabindex="-1">최소 kubelet configuration <a class="header-anchor" href="#최소-kubelet-configuration" aria-label="Permalink to &quot;최소 kubelet configuration&quot;">​</a></h2><p>NUMA-aligned GPU node pool을 별도로 운영한다면 원문은 다음 계열의 kubelet 설정을 제시한다.</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">cpuManagerPolicy</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">static</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">cpuManagerPolicyOptions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  full-pcpus-only</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;true&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">topologyManagerPolicy</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">single-numa-node</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Default is container. Use pod only when the whole pod should fit on one NUMA node.</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># topologyManagerScope: pod</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">memoryManagerPolicy</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Static</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># memoryManagerPolicy: Static requires reservedMemory to be configured.</span></span></code></pre></div><p>CPU Manager나 Memory Manager policy를 바꿀 때는 drained node에서 적용해야 한다. Kubelet restart 전에 CPU/memory manager state file을 지워야 하는 경우도 있다. 운영 중인 mixed workload node에 바로 켜면 기존 pod sizing과 충돌할 수 있다.</p><h2 id="kubelet-cpu-allocation이-만드는-조용한-성능-저하" tabindex="-1">Kubelet CPU allocation이 만드는 조용한 성능 저하 <a class="header-anchor" href="#kubelet-cpu-allocation이-만드는-조용한-성능-저하" aria-label="Permalink to &quot;Kubelet CPU allocation이 만드는 조용한 성능 저하&quot;">​</a></h2><p><code>cpuManagerPolicy: static</code>의 packed allocation은 대체로 좋은 방향이다. Kubelet은 full NUMA node, full physical core, individual logical core 순서로 CPU를 가져오며, 가능한 한 이미 많이 사용된 NUMA node를 먼저 채워 fragmentation을 줄이려 한다.</p><p>하지만 &quot;가능하면 local&quot;은 보장이 아니다.</p><p>예를 들어 2-socket machine이 있고 socket당 48 physical core, SMT 포함 96 vCPU가 있다고 하자. Reservation 이후 각 NUMA node에 90 allocatable vCPU와 4 GPU가 있다고 가정한다. Pod 하나가 GPU 1개와 22 vCPU를 request하면 처음 4개 pod는 NUMA 0에 잘 들어간다.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>4 pods x 22 vCPU = 88 vCPU</span></span>
<span class="line"><span>NUMA 0 remaining = 2 vCPU</span></span></code></pre></div><p>5번째 pod가 22 vCPU를 요청하면 NUMA 0에는 2 vCPU만 남아 있다. <code>single-numa-node</code>가 없다면 CPU Manager는 2 vCPU를 NUMA 0에서, 나머지 20 vCPU를 NUMA 1에서 가져올 수 있다. Pod는 정상 실행되지만 CPU가 NUMA boundary를 걸친다.</p><p>이것이 가장 위험한 실패 모드다. Pod는 실패하지 않는다. Kubernetes event도 성능 저하를 알려주지 않는다. 사용자는 p99 latency나 throughput variance를 보고 나서야 문제를 발견한다.</p><h2 id="failure-mode-1-smtalignmenterror" tabindex="-1">Failure Mode 1: <code>SMTAlignmentError</code> <a class="header-anchor" href="#failure-mode-1-smtalignmenterror" aria-label="Permalink to &quot;Failure Mode 1: \`SMTAlignmentError\`&quot;">​</a></h2><p><code>full-pcpus-only=true</code>를 켜면 exclusive CPU를 받는 container의 CPU request가 SMT thread 수의 배수가 아니면 kubelet이 pod를 거부한다.</p><p>예를 들어 2-way SMT 환경에서 pinned container가 3 CPU를 request하면 physical core를 온전히 줄 수 없다. 이 경우 <code>SMTAlignmentError</code>가 발생한다. Deployment나 StatefulSet controller가 pod를 재생성해도 같은 node pool에서는 같은 이유로 계속 실패한다.</p><p>대응은 단순하지만 사전 준비가 필요하다.</p><ul><li>pinned container CPU request를 even number로 조정한다.</li><li>sidecar와 init container의 request/limit이 pod QoS를 깨지 않는지 확인한다.</li><li><code>full-pcpus-only</code>를 켜는 node pool을 별도로 만든다.</li></ul><h2 id="failure-mode-2-topologyaffinityerror" tabindex="-1">Failure Mode 2: <code>TopologyAffinityError</code> <a class="header-anchor" href="#failure-mode-2-topologyaffinityerror" aria-label="Permalink to &quot;Failure Mode 2: \`TopologyAffinityError\`&quot;">​</a></h2><p><code>topologyManagerPolicy: single-numa-node</code>를 켜면 kubelet은 CPU, device, memory topology hint를 모아 단일 NUMA node에서 만족 가능한지 본다. 불가능하면 pod는 <code>TopologyAffinityError</code>로 admission 단계에서 실패한다.</p><p>이 실패는 처음에는 혼란스럽다. Node 전체 aggregate resource는 충분해 보일 수 있기 때문이다.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Node free CPU = 60 vCPU</span></span>
<span class="line"><span>NUMA 0 free = 20 vCPU</span></span>
<span class="line"><span>NUMA 1 free = 40 vCPU</span></span>
<span class="line"><span>Pod request = 48 vCPU</span></span></code></pre></div><p>총량으로는 60 vCPU가 있어 보이지만, 어떤 단일 NUMA node도 48 vCPU를 제공하지 못한다. <code>single-numa-node</code>에서는 이런 pod를 받아들이지 않는 것이 맞다. 조용히 느려지는 것보다 명시적으로 실패하는 편이 latency-sensitive GPU service에는 더 낫다.</p><h2 id="topology-aware-scheduling이-필요한-이유" tabindex="-1">Topology-aware scheduling이 필요한 이유 <a class="header-anchor" href="#topology-aware-scheduling이-필요한-이유" aria-label="Permalink to &quot;Topology-aware scheduling이 필요한 이유&quot;">​</a></h2><p>기본 Kubernetes scheduler는 node의 aggregate resource를 보고 scheduling한다. NUMA node별 잔여 CPU, memory, GPU locality를 알지 못한다. 따라서 scheduler는 pod를 node에 보냈지만 kubelet이 topology admission에서 거부하는 일이 생긴다.</p><p>이 gap을 줄이려면 topology-aware scheduling이 필요하다.</p>`,47)),(t(),o(r,null,{default:a(()=>[l(s,{id:"mermaid-379",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20A%5BPod%20request%3Cbr%2F%3EGPU%20%2B%20CPU%20%2B%20memory%5D%20--%3E%20B%5BDefault%20scheduler%3Cbr%2F%3Esees%20aggregate%20node%20resource%5D%0A%20%20%20%20B%20--%3E%20C%5BKubelet%20topology%20admission%5D%0A%20%20%20%20C%20--%3E%20D%7BSingle%20NUMA%20node%3Cbr%2F%3Ecan%20satisfy%20hints%3F%7D%0A%20%20%20%20D%20--%3E%7Cyes%7C%20E%5BAdmit%20pod%3Cbr%2F%3ENUMA-local%20execution%5D%0A%20%20%20%20D%20--%3E%7Cno%7C%20F%5BTopologyAffinityError%3Cbr%2F%3Epod%20fails%20after%20scheduling%5D%0A%20%20%20%20B%20-.%20topology-aware%20path%20.-%3E%20G%5BNodeResourceTopologyMatch%3Cbr%2F%3Efilters%20by%20NUMA-local%20capacity%5D%0A%20%20%20%20G%20--%3E%20H%5BChoose%20node%20with%3Cbr%2F%3Evalid%20NUMA%20fit%5D%0A%20%20%20%20H%20--%3E%20E%0A%0A%20%20%20%20classDef%20primary%20fill%3A%23F5F1EA%2Cstroke%3A%23111111%2Cstroke-width%3A1.4px%2Ccolor%3A%23050505%0A%20%20%20%20classDef%20secondary%20fill%3A%23F3EFE7%2Cstroke%3A%23D8D1C7%2Cstroke-width%3A1.2px%2Ccolor%3A%23050505%0A%20%20%20%20classDef%20note%20fill%3A%23F5F1EA%2Cstroke%3A%23D8D1C7%2Cstroke-width%3A1px%2Ccolor%3A%236F6A63%0A%20%20%20%20classDef%20accent%20fill%3A%23F5F1EA%2Cstroke%3A%23D9392E%2Cstroke-width%3A2px%2Ccolor%3A%23050505%0A%20%20%20%20class%20A%20primary%0A%20%20%20%20class%20B%2CC%2CG%2CH%20secondary%0A%20%20%20%20class%20D%20note%0A%20%20%20%20class%20F%20accent%0A%20%20%20%20class%20E%20primary%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[n(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=i(`<table tabindex="0"><thead><tr><th>Component</th><th>Role</th></tr></thead><tbody><tr><td><code>NodeResourceTopology</code> CRD</td><td>node별 NUMA resource 정보를 cluster object로 표현</td></tr><tr><td>NFD Topology Updater</td><td>kubelet PodResources API 등을 보고 NUMA별 available resource를 갱신</td></tr><tr><td><code>NodeResourceTopologyMatch</code> scheduler plugin</td><td>scheduler가 topology constraint를 고려해 node를 filter/score</td></tr></tbody></table><p>이 구성을 넣으면 scheduler가 &quot;총량은 충분하지만 단일 NUMA node에는 부족한 node&quot;를 미리 걸러낼 수 있다. 단점은 platform team이 운영해야 할 component가 늘어난다는 점이다. DaemonSet, CRD, scheduler plugin cache, update interval을 모두 이해해야 한다.</p><h2 id="platform-team과-workload-owner의-계약" tabindex="-1">Platform team과 workload owner의 계약 <a class="header-anchor" href="#platform-team과-workload-owner의-계약" aria-label="Permalink to &quot;Platform team과 workload owner의 계약&quot;">​</a></h2><p>원문에서 가장 실무적인 부분은 NUMA alignment가 platform team 혼자 해결할 수 있는 문제가 아니라는 점이다. Workload owner도 sizing constraint를 이해해야 한다.</p><p>Platform team이 제공해야 할 정보:</p><table tabindex="0"><thead><tr><th>Information</th><th>Why it matters</th></tr></thead><tbody><tr><td>node pool SKU</td><td>core count, GPU count, NIC placement가 SKU마다 다름</td></tr><tr><td>NUMA geometry</td><td>NUMA node별 core, memory, GPU mapping</td></tr><tr><td>NPS mode</td><td>AMD EPYC에서 socket이 몇 NUMA node로 쪼개지는지 결정</td></tr><tr><td>system/kube reserved CPU</td><td>workload가 실제로 쓸 수 있는 NUMA별 allocatable CPU 계산</td></tr><tr><td>recommended CPU per GPU</td><td>pod sizing이 NUMA node 안에 들어오게 유도</td></tr><tr><td>enabled constraints</td><td><code>full-pcpus-only</code>, <code>single-numa-node</code>, topology scope, Memory Manager</td></tr><tr><td>expected failure modes</td><td><code>SMTAlignmentError</code>, <code>TopologyAffinityError</code>를 workload owner가 이해해야 함</td></tr></tbody></table><p>Workload owner가 해야 할 일:</p><table tabindex="0"><thead><tr><th>Action</th><th>Why it matters</th></tr></thead><tbody><tr><td>CPU/memory request를 실제 peak에 맞춤</td><td>Guaranteed QoS와 admission success에 필요</td></tr><tr><td>한 NUMA node 안에 들어가는 pod size 선택</td><td>큰 pod 하나보다 작은 NUMA-local pod 여러 개가 나을 수 있음</td></tr><tr><td>even CPU request 사용</td><td><code>full-pcpus-only</code> node pool에서 필요</td></tr><tr><td>sidecar/init container 확인</td><td>pod QoS와 topology scope에 영향</td></tr><tr><td>SKU 변경 시 sizing 재검토</td><td>NUMA geometry는 hardware와 BIOS setting에 따라 달라짐</td></tr></tbody></table><h2 id="검증-명령" tabindex="-1">검증 명령 <a class="header-anchor" href="#검증-명령" aria-label="Permalink to &quot;검증 명령&quot;">​</a></h2><p>Node topology:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lscpu</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e=CPU,CORE,SOCKET,NODE</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">numactl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -H</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nvidia-smi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> topo</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span></span></code></pre></div><p>Container CPU affinity:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">pod-nam</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">container-nam</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> taskset</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -cp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">pod-nam</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">container-nam</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> grep</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Cpus_allowed_list</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /proc/1/status</span></span></code></pre></div><p>Kubelet policy:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> describe</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> node</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">node-nam</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><p>Pod event 확인:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> describe</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pod</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">pod-nam</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> events</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --sort-by=.lastTimestamp</span></span></code></pre></div><p>확인할 것은 단순히 pod가 Running인지가 아니다. CPU affinity가 기대한 NUMA node 안에 들어오는지, GPU가 그 NUMA node에 붙어 있는지, memory request가 해당 NUMA node 안에 들어갈 수 있는지 봐야 한다.</p><h2 id="dra와-향후-방향" tabindex="-1">DRA와 향후 방향 <a class="header-anchor" href="#dra와-향후-방향" aria-label="Permalink to &quot;DRA와 향후 방향&quot;">​</a></h2><p>원문은 Kubernetes DRA(Dynamic Resource Allocation) CPU driver를 future direction으로 언급한다. DRA는 resource allocation을 더 scheduling layer에 가깝게 끌어올려, kubelet admission 단계에서 뒤늦게 실패하는 문제를 줄일 가능성이 있다.</p><p>다만 글에서는 아직 충분히 검증하지 않았기 때문에 권장안으로 제시하지는 않는다. 현재 production 판단에서는 CPU Manager, Topology Manager, Memory Manager, topology-aware scheduler plugin 조합이 더 직접적인 선택지다.</p><h2 id="training-workload에-적용하기" tabindex="-1">Training workload에 적용하기 <a class="header-anchor" href="#training-workload에-적용하기" aria-label="Permalink to &quot;Training workload에 적용하기&quot;">​</a></h2><p>Training에서는 다음 상황에서 NUMA alignment를 우선 검토한다.</p><table tabindex="0"><thead><tr><th>Symptom</th><th>First checks</th></tr></thead><tbody><tr><td>GPU utilization sawtooth</td><td>dataloader wait time, CPU affinity, pinned memory NUMA locality</td></tr><tr><td>step time variance 증가</td><td>CPU run queue, remote memory access, I/O wait</td></tr><tr><td>NCCL bandwidth 낮음</td><td>GPU/NIC locality, <code>nvidia-smi topo -m</code>, selected interface</td></tr><tr><td>MoE all-to-all variance</td><td>GPU/NIC topology, CPU scheduling jitter, expert placement</td></tr><tr><td>host memory pressure</td><td>cgroup memory limit, Memory Manager, NUMA별 free memory</td></tr></tbody></table><p>큰 training job은 보통 GPU 수와 network topology를 먼저 본다. 하지만 node 안에서 CPU와 memory가 GPU-local하지 않으면 expensive accelerator가 batch를 기다릴 수 있다.</p><h2 id="inference-workload에-적용하기" tabindex="-1">Inference workload에 적용하기 <a class="header-anchor" href="#inference-workload에-적용하기" aria-label="Permalink to &quot;Inference workload에 적용하기&quot;">​</a></h2><p>Inference에서는 다음 질문이 중요하다.</p><table tabindex="0"><thead><tr><th>Question</th><th>Why it matters</th></tr></thead><tbody><tr><td>tokenizer와 batching thread가 GPU-local CPU에서 도는가?</td><td>TTFT와 p99 latency에 영향</td></tr><tr><td>pod CPU가 두 socket에 걸치는가?</td><td>H2D path와 cache locality가 흔들릴 수 있음</td></tr><tr><td>GPU plugin이 NUMA topology hint를 제공하는가?</td><td>Topology Manager가 CPU-GPU locality를 강제할 수 있는 전제</td></tr><tr><td>p99가 특정 node/pod에서만 높은가?</td><td>misaligned pod가 조용히 serving 중일 수 있음</td></tr><tr><td>큰 pod 하나보다 작은 replica 여러 개가 나은가?</td><td>NUMA-local sizing과 autoscaling 효율</td></tr></tbody></table><p>LLM serving에서는 GPU kernel 최적화만으로 p99를 설명할 수 없다. CPU preprocessing, scheduler, memory copy, postprocessing이 GPU 앞뒤에 붙어 있기 때문에 NUMA locality는 serving path의 일부다.</p><h2 id="실무-결론" tabindex="-1">실무 결론 <a class="header-anchor" href="#실무-결론" aria-label="Permalink to &quot;실무 결론&quot;">​</a></h2><ol><li>GPU workload의 CPU는 control plane만이 아니라 data path다.</li><li>CPU pinning은 <code>cpuManagerPolicy: static</code>과 Guaranteed QoS 조건이 있어야 의미가 생긴다.</li><li><code>full-pcpus-only</code>는 physical core isolation을 주지만 CPU request 제약을 만든다.</li><li><code>single-numa-node</code>는 조용한 성능 저하를 admission failure로 바꾼다.</li><li>Memory locality까지 보려면 <code>memoryManagerPolicy: Static</code>과 <code>reservedMemory</code>가 필요하다.</li><li>Device plugin이 topology hint를 주지 않으면 Topology Manager가 CPU-GPU locality를 강제할 수 없다.</li><li>기본 scheduler는 NUMA별 잔여 resource를 모르므로 topology-aware scheduling이 필요할 수 있다.</li><li>Platform team은 node pool별 NUMA geometry와 recommended pod size를 문서화해야 한다.</li><li>Workload owner는 &quot;CPU 몇 개&quot;가 아니라 &quot;한 NUMA node 안에 들어가는 CPU/memory/GPU 조합&quot;으로 request를 설계해야 한다.</li></ol><h2 id="이-레포와의-연결" tabindex="-1">이 레포와의 연결 <a class="header-anchor" href="#이-레포와의-연결" aria-label="Permalink to &quot;이 레포와의 연결&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Topic</th><th>Connection</th></tr></thead><tbody><tr><td>Chapter 3: OS, Docker, and Kubernetes Tuning</td><td>CPU Manager, Topology Manager, Memory Manager, Guaranteed QoS의 실무 적용</td></tr><tr><td>Chapter 4: Distributed Networking Communication</td><td>GPU/NIC locality와 RDMA/NCCL path 확인</td></tr><tr><td>Training notes</td><td>dataloader, pinned memory, MoE, step time variance</td></tr><tr><td>Efficient LLM Inference Systems</td><td>tokenizer, batching, H2D copy, serving p99 tail latency</td></tr><tr><td>Never Underestimate Memory Architecture</td><td>NUMA와 uncore가 왜 성능 모델의 일부인지 설명하는 배경 자료</td></tr></tbody></table><h2 id="후속-질문" tabindex="-1">후속 질문 <a class="header-anchor" href="#후속-질문" aria-label="Permalink to &quot;후속 질문&quot;">​</a></h2><ol><li>현재 GPU node pool의 NUMA node별 CPU, memory, GPU, NIC mapping은 문서화되어 있는가?</li><li><code>nvidia-device-plugin</code>이 NUMA <code>TopologyInfo</code>를 제공하고 있는가?</li><li>GPU pod는 Guaranteed QoS, integer CPU request, even CPU request 조건을 만족하는가?</li><li><code>single-numa-node</code>를 켰을 때 실패할 workload가 있는가?</li><li>Scheduler가 NUMA별 잔여 resource를 보지 못해서 kubelet admission failure loop가 생길 수 있는가?</li><li>Platform team이 workload owner에게 recommended CPU-per-GPU sizing matrix를 제공하고 있는가?</li></ol>`,35))])}const A=d(k,[["render",u]]);export{P as __pageData,A as default};
